// Regla de un bus: solo los pedidos creados por tienda.pedidos con un total mayor que 100.
export const patron = {
  source: ["tienda.pedidos"],
  "detail-type": ["Pedido creado"],
  detail: { total: [{ numeric: [">", 100] }] },
};

// Un evento tiene la misma estructura que el patrón que lo casa.
const evento = {
  source: "tienda.pedidos",
  "detail-type": "Pedido creado",
  detail: { pedidoId: "P-1", total: 250 },
};

// Con el arnés:
// aws.events.validatePattern(patron) debe dar [] (un patrón se puede evaluar).
// aws.events.matches(patron, evento) da true; con total: 40 daría false.
// Los campos del evento que el patrón no menciona (como pedidoId) se ignoran.

